function clamp(value, min, max) {
  if (value < min) {
    return min;
  } else if (value > max) {
    return max;
  } else {
    return value;
  }
}

module.exports = clamp;

import { clamp } from './clamp.js';

const assert = require('assert');

describe('clamp', function() {
  it('should return the min value if the input value is below the range', function() {
    assert.strictEqual(clamp(-5, 0, 10), 0);
  });

  it('should return the max value if the input value is above the range', function() {
    assert.strictEqual(clamp(15, 0, 10), 10);
  });

  it('should return the value itself if it is within the range', function() {
    assert.strictEqual(clamp(5, 0, 10), 5);
  });
});
